output.raw:
{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm curious — do you have any squares you can share? I need one for my order and I'm thinking we could trade something back. What do you think?"
    }
  },
  "rationale": "I need a square to fulfill my order, and since B has the specialty square, they're the best source. Starting a casual conversation opens up a trade opportunity without pressure."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "A"
      ],
      "content": "Hey, I'm working on producing squares since that's my specialty. I'm thinking we could trade some squares for circles if you're open to it. What do you think?"
    }
  },
  "rationale": "I have a specialty shape (square) that others need, so initiating a trade proposal with A makes sense. Since A has the circle order, they might be willing to trade for my squares."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "C"
      ],
      "content": "Hey, I'm working on getting a triangle for my order. Since you're the one who makes triangles, I was wondering if you'd be open to trading one for a circle? I can give you $20 for it."
    }
  },
  "rationale": "I need a triangle to fulfill my order, and C has the specialty shape. A direct, low-pressure message to propose a fair trade makes sense given my limited production capacity and the need to act quickly."
}

